    amount: Optional[Money] = None
    note: str = ""


@dataclass
class Transaction:
    date: date
    payee: str
    narration: str = ""
    postings: List[Posting] = field(default_factory=list)
    tags: Tuple[str, ...] = ()
    flag: str = "*"
    id: Optional[int] = None
