"""Money: integer minor units plus a currency code. No floats anywhere."""
import re

from tallybook.currency import CurrencyError, currency as _currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    pass


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """Quotient n/d rounded half away from zero (d > 0)."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, currency):
    exponent = _currency(currency).exponent
    if not _is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if exponent == 0:
        return sign + digits
    digits = digits.rjust(exponent + 1, "0")
    return "%s%s.%s" % (sign, digits[:-exponent], digits[-exponent:])


def parse_amount(text, currency):
    exponent = _currency(currency).exponent
    if not isinstance(text, str):
        raise MoneyError("amount must be text, got %r" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if m is None:
        raise MoneyError("invalid amount %r" % (text,))
    sign, whole, frac = m.groups()
    frac = frac or ""
    if m.group(3) is not None and exponent == 0:
        raise MoneyError("invalid amount %r: %s has no decimals" % (text, currency))
    if len(frac) > exponent:
        raise MoneyError("invalid amount %r: %s has only %d decimals" % (text, currency, exponent))
    minor = int(whole + frac.ljust(exponent, "0"))
    return -minor if sign == "-" else minor


class Money:
    __slots__ = ("minor", "currency")

    def __init__(self, minor, currency):
        if not _is_int(minor):
            raise MoneyError("minor units must be an integer, got %r" % (minor,))
        _currency(currency)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "currency", currency)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self.minor, self.currency))

    @classmethod
    def zero(cls, currency):
        return cls(0, currency)

    @classmethod
    def of(cls, text, currency):
        return cls(parse_amount(text, currency), currency)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("money must be text like '12.50 USD', got %r" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise MoneyError("invalid money %r: expected AMOUNT and CURRENCY separated by one space" % (text,))
        return cls.of(parts[0], parts[1])

    @property
    def exponent(self):
        return _currency(self.currency).exponent

    def amount_str(self):
        return format_minor(self.minor, self.currency)

    def __repr__(self):
        return "Money(%d, %r)" % (self.minor, self.currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self.currency)

    def __hash__(self):
        return hash((self.minor, self.currency))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self.minor == other.minor and self.currency == other.currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def _same(self, other, verb):
        if self.currency != other.currency:
            raise MoneyError("cannot %s %s and %s: different currencies" % (verb, self.currency, other.currency))

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self.minor + other.minor, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self.minor - other.minor, self.currency)

    def __neg__(self):
        return Money(-self.minor, self.currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self.minor), self.currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self.minor * other, self.currency)

    __rmul__ = __mul__

    def _cmp(self, other):
        if not isinstance(other, Money):
            return None
        self._same(other, "compare")
        return (self.minor > other.minor) - (self.minor < other.minor)

    def __lt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c < 0

    def __le__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c <= 0

    def __gt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c > 0

    def __ge__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c >= 0

    def is_zero(self):
        return self.minor == 0

    def sign(self):
        return (self.minor > 0) - (self.minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integer numerator and denominator")
        if den == 0:
            raise MoneyError("scale denominator may not be zero")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self.minor * num, den), self.currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)):
            raise MoneyError("weights must be a list of integers")
        weights = list(weights)
        if not weights or any(not _is_int(w) or w < 0 for w in weights):
            raise MoneyError("weights must be a non-empty list of non-negative integers")
        total = sum(weights)
        if total <= 0:
            raise MoneyError("weights must sum to more than zero")
        amount = abs(self.minor)
        shares = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        leftover = amount - sum(shares)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:leftover]:
            shares[i] += 1
        if self.minor < 0:
            shares = [-s for s in shares]
        return [Money(s, self.currency) for s in shares]
"""Currency table and exchange rates."""
import re
from dataclasses import dataclass
from fractions import Fraction

from tallybook.dates import is_date
from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    pass


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


CURRENCIES = {
    c.code: c
    for c in (
        Currency("USD", 2, "US Dollar", "$"),
        Currency("EUR", 2, "Euro", "€"),
        Currency("GBP", 2, "British Pound", "£"),
        Currency("JPY", 0, "Japanese Yen", "¥"),
        Currency("CHF", 2, "Swiss Franc", "CHF"),
        Currency("CAD", 2, "Canadian Dollar", "CA$"),
        Currency("AUD", 2, "Australian Dollar", "A$"),
        Currency("KWD", 3, "Kuwaiti Dinar", "KD"),
        Currency("SEK", 2, "Swedish Krona", "kr"),
        Currency("INR", 2, "Indian Rupee", "₹"),
        Currency("NZD", 2, "New Zealand Dollar", "NZ$"),
        Currency("NOK", 2, "Norwegian Krone", "kr"),
        Currency("KRW", 0, "South Korean Won", "₩"),
        Currency("BHD", 3, "Bahraini Dinar", "BD"),
        Currency("CNY", 2, "Chinese Yuan", "CN¥"),
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    )
}


def currency(code):
    if not isinstance(code, str) or code not in CURRENCIES:
        raise CurrencyError("unknown currency %r" % (code,))
    return CURRENCIES[code]


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def _check_date(on):
    if not is_date(on):
        raise CurrencyError("date must be a datetime.date, got %r" % (on,))


class RateTable:
    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: Fraction}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        if not isinstance(rate_text, str) or _RATE_RE.fullmatch(rate_text) is None:
            raise CurrencyError("invalid rate %r: expected digits with up to 8 decimals" % (rate_text,))
        rate = Fraction(rate_text)
        if rate <= 0:
            raise CurrencyError("invalid rate %r: must be positive" % (rate_text,))
        _check_date(on)
        self._rates.setdefault((src, dst), {})[on] = rate

    def _lookup(self, src, dst, on):
        best = None
        for d, r in self._rates.get((src, dst), {}).items():
            if d <= on and (best is None or d > best[0]):
                best = (d, r)
        return None if best is None else best[1]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._lookup(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._lookup(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, on.isoformat()))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("can only convert Money, got %r" % (money,))
        dst_cur = currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        rate = self.rate(money.currency, dst, on)
        value = Fraction(money.minor) * rate * Fraction(10) ** (dst_cur.exponent - money.exponent)
        return Money(round_div(value.numerator, value.denominator), dst)

    def entries(self):
        out = []
        for (src, dst), by_date in self._rates.items():
            for d, r in by_date.items():
                out.append((src, dst, d, r))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        by_date = self._rates.get((src, dst))
        if not by_date or on not in by_date:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, on.isoformat()))
        del by_date[on]
        if not by_date:
            del self._rates[(src, dst)]

