"""Strict dates, month arithmetic and periods."""
import calendar
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    pass


def is_date(value):
    return isinstance(value, date) and not isinstance(value, datetime)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %r: expected text YYYY-MM-DD" % (text,))
    m = _DATE_RE.fullmatch(text)
    if m is None:
        raise DateError("invalid date %r: expected YYYY-MM-DD" % (text,))
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date %r: no such day" % (text,)) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers, got %r and %r" % (year, month))
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise DateError("year/month out of range: %r-%r" % (year, month))
    return calendar.monthrange(year, month)[1]


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    year, month0 = divmod(total, 12)
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s %+d months" % (format_date(d), n))
    month = month0 + 1
    return date(year, month, min(d.day, calendar.monthrange(year, month)[1]))


def _add_days(d, n):
    try:
        return d + timedelta(days=n)
    except OverflowError:
        raise DateError("date out of range: %s %+d days" % (format_date(d), n)) from None


_PERIOD_YEAR = re.compile(r"([0-9]{4})")
_PERIOD_MONTH = re.compile(r"([0-9]{4})-([0-9]{2})")
_PERIOD_QUARTER = re.compile(r"([0-9]{4})-Q([1-4])")
_PERIOD_RANGE = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})")


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got %r and %r" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: end %s is before start %s" % (format_date(self.end), format_date(self.start)))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            m = _PERIOD_YEAR.fullmatch(text)
            if m:
                y = int(m.group(1))
                return cls(date(y, 1, 1), date(y, 12, 31))
            m = _PERIOD_MONTH.fullmatch(text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(date(y, mo, 1), date(y, mo, calendar.monthrange(y, mo)[1]))
            m = _PERIOD_QUARTER.fullmatch(text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                first = 3 * q - 2
                return cls(date(y, first, 1), date(y, first + 2, calendar.monthrange(y, first + 2)[1]))
            m = _PERIOD_RANGE.fullmatch(text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (ValueError, calendar.IllegalMonthError, DateError):
            pass
        raise DateError("invalid period %r: expected 2024, 2024-03, 2024-Q1 or 2024-03-01..2024-03-31" % (text,))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.month == 1 and s.day == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if s.day == 1 and e.year == s.year and e.month == s.month and e.day == calendar.monthrange(s.year, s.month)[1]:
            return "month"
        if (
            s.day == 1
            and s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == calendar.monthrange(e.year, e.month)[1]
        ):
            return "quarter"
        return "range"

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return _whole("year", s.year + 1, 1)
        if kind == "month":
            nxt = add_months(s, 1)
            return _whole("month", nxt.year, nxt.month)
        if kind == "quarter":
            nxt = add_months(s, 3)
            return _whole("quarter", nxt.year, nxt.month)
        start = _add_days(self.end, 1)
        return Period(start, _add_days(start, self.days - 1))


def _whole(kind, year, month):
    if not 1 <= year <= 9999:
        raise DateError("date out of range: year %d" % year)
    if kind == "year":
        return Period(date(year, 1, 1), date(year, 12, 31))
    if kind == "month":
        return Period(date(year, month, 1), date(year, month, calendar.monthrange(year, month)[1]))
    return Period(date(year, month, 1), date(year, month + 2, calendar.monthrange(year, month + 2)[1]))


_STEPS = ("week", "month", "quarter", "year")


def _period_containing(d, step):
    if step == "week":
        monday = _add_days(d, -d.weekday())
        return Period(monday, _add_days(monday, 6))
    if step == "month":
        return _whole("month", d.year, d.month)
    if step == "quarter":
        return _whole("quarter", d.year, 3 * ((d.month - 1) // 3) + 1)
    return _whole("year", d.year, 1)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got %r and %r" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step %r: expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _period_containing(start, step)
    out = [p]
    while p.end < end:
        p = p.next() if step != "week" else Period(_add_days(p.end, 1), _add_days(p.end, 7))
        out.append(p)
    return out
"""Chart of accounts."""
import re

from tallybook.currency import CURRENCIES
from tallybook.dates import format_date, is_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    pass


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEGMENT.fullmatch(p) is not None for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,))


def parent_path(path):
    _need_path(path)
    return path.rsplit(":", 1)[0] if ":" in path else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _sort_key(path):
    return tuple(path.split(":"))


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and _SEGMENT.fullmatch(p) is None:
            raise ChartError("invalid account pattern %r" % (pattern,))
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern segments, segs: list of path segments; exact match.
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for take in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[take:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def _pattern_matches(parts, path):
    segs = path.split(":")
    if all(p not in ("*", "**") for p in parts):
        return segs[: len(parts)] == parts
    return _match_segments(parts, segs)


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    return _pattern_matches(parts, path)


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        root_type = account_type(path)
        if type is not None and (not isinstance(type, str) or type not in TYPES or type != root_type):
            raise ChartError("account type %r does not fit %s" % (type, path))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text, got %r" % (note,))
        if path in self._explicit:
            err = ChartError("account %s already exists" % path)
            err.code = "conflict"
            raise err
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            account = existing
        else:
            account = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = account
        self._explicit.add(path)
        parent = parent_path(path)
        while parent is not None:
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, root_type)
            parent = parent_path(parent)
        return account

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def is_explicit(self, path):
        return path in self._explicit

    def children(self, path):
        self.get(path)
        depth = path.count(":") + 1
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix) and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        account = self.get(path)
        if not is_date(on):
            raise ChartError("date must be a date, got %r" % (on,))
        return (account.opened is None or account.opened <= on) and (account.closed is None or on <= account.closed)

    def close(self, path, on):
        account = self.get(path)
        if not is_date(on):
            raise ChartError("close date must be a date, got %r" % (on,))
        if account.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if account.opened is not None and on < account.opened:
            raise ChartError("cannot close %s on %s: before it opened on %s" % (path, format_date(on), format_date(account.opened)))
        account.closed = on
        return account

    def matches(self, pattern):
        parts = _check_pattern(pattern)
        return [a for a in self.accounts() if _pattern_matches(parts, a.path)]

