"""The ledger: validated transactions and balances."""
import re

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.dates import format_date, is_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor


class LedgerError(ValidationError):
    pass


_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _line_free(text):
    return isinstance(text, str) and "\n" not in text and "\r" not in text


def _copy(tx):
    return Transaction(tx.date, tx.payee, tx.narration, list(tx.postings), tuple(tx.tags), tx.flag, tx.id)


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation ---------------------------------------------------
    def _build(self, tx, forced_id=None, check_id=True):
        if not isinstance(tx, Transaction):
            raise LedgerError("expected a Transaction, got %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("date must be a datetime.date, got %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("flag must be '*' or '!', got %r" % (tx.flag,))
        if not _line_free(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _line_free(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if isinstance(tx.tags, str):
            raise LedgerError("tags must be a sequence of tag names")
        try:
            tags = list(tx.tags)
        except TypeError:
            raise LedgerError("tags must be a sequence of tag names") from None
        for tag in tags:
            if not isinstance(tag, str) or _TAG.fullmatch(tag) is None:
                raise LedgerError("invalid tag %r" % (tag,))
        try:
            postings = list(tx.postings)
        except TypeError:
            raise LedgerError("postings must be a list") from None
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("expected a Posting, got %r" % (p,))
            if not isinstance(p.account, str):
                raise LedgerError("posting account must be text, got %r" % (p.account,))
            if not _line_free(p.note):
                raise LedgerError("posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be Money or None, got %r" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % p.account)
        for p in postings:
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
        self._check_currencies(postings)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = {c: v for c, v in sums.items() if v != 0}
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = [Posting(gap.account, Money(-off[c], c), gap.note) for c in sorted(off)]
            postings = postings[:i] + filled + postings[i + 1 :]
            self._check_currencies(filled)
        elif off:
            detail = ", ".join("%s %s" % (c, format_minor(off[c], c)) for c in sorted(off))
            raise LedgerError("transaction does not balance: %s" % detail)
        if forced_id is not None:
            tid = forced_id
        elif tx.id is None:
            tid = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("id must be an integer of at least 1, got %r" % (tx.id,))
            if check_id and tx.id in self._txs:
                raise LedgerError("transaction id %d already exists" % tx.id)
            tid = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings, tuple(sorted(set(tags))), tx.flag, tid)

    def _check_currencies(self, postings):
        for p in postings:
            if p.amount is None:
                continue
            held = self.chart.get(p.account).currency
            if held is not None and held != p.amount.currency:
                raise LedgerError("account %s only holds %s, not %s" % (p.account, held, p.amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- writes -------------------------------------------------------
    def add(self, tx):
        stored = self._build(tx)
        self._store(stored)
        return _copy(stored)

    def add_many(self, transactions):
        saved_txs, saved_max = dict(self._txs), self._max_id
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = saved_txs, saved_max
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if isinstance(tx, Transaction) and tx.id is not None and tx.id != id:
            raise LedgerError("replacement id %r does not match %r" % (tx.id, id))
        stored = self._build(tx, forced_id=id)
        self._txs[id] = stored
        return _copy(stored)

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return _copy(self._txs.pop(id))

    # -- reads --------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return _copy(self._txs[id])

    def _sorted(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def transactions(self):
        return [_copy(t) for t in self._sorted()]

    def postings(self):
        for tx in self._sorted():
            copy = _copy(tx)
            for p in copy.postings:
                yield copy, p

    def _selected(self, as_of):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date or None, got %r" % (as_of,))
        for tx in self._txs.values():
            if as_of is None or tx.date <= as_of:
                yield tx

    def balances(self, as_of=None):
        totals = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                cur = totals.setdefault(p.account, {})
                cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
        return _clean(totals)

    def rollup_balances(self, as_of=None):
        totals = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                path = p.account
                while True:
                    cur = totals.setdefault(path, {})
                    cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
                    if ":" not in path:
                        break
                    path = path.rsplit(":", 1)[0]
        return _clean(totals)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        prefix = account + ":"
        sums = {}
        for tx in self._selected(as_of):
            for p in tx.postings:
                if p.account == account or (rollup and p.account.startswith(prefix)):
                    c = p.amount.currency
                    sums[c] = sums.get(c, 0) + p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}


def _clean(totals):
    out = {}
    for account, cur in totals.items():
        kept = {c: v for c, v in cur.items() if v != 0}
        if kept:
            out[account] = kept
    return out
"""CSV / JSON export, JSON import and plain text tables."""
import json

from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, MoneyError
from tallybook.currency import CurrencyError


class ExportError(ValidationError):
    pass


def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _csv_field(value):
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


_CSV_HEADER = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            format_date(tx.date),
            tx.flag,
            tx.payee,
            tx.narration,
            ";".join(sorted(set(tx.tags))),
        ]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, "", "", p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(_CSV_HEADER, rows)


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note} for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


def _clean_cell(cell):
    text = "" if cell is None else str(cell)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_clean_cell(h) for h in headers]
    if not headers:
        return ""
    n = len(headers)
    if align is None:
        letters = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string or a list of 'l'/'r'")
        letters = list(align)
        if len(letters) != n or any(a not in ("l", "r") for a in letters):
            raise ExportError("align must hold one 'l' or 'r' per column (%d columns)" % n)
    body = []
    for row in rows:
        cells = [_clean_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("row has %d cells, expected %d" % (len(cells), n))
        body.append(cells)
    widths = [max([len(headers[i])] + [len(r[i]) for r in body]) for i in range(n)]

    def line(cells):
        parts = [c.rjust(w) if a == "r" else c.ljust(w) for c, w, a in zip(cells, widths, letters)]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in body)
    return "".join(out)


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _posting_from_obj(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: posting must be an object" % where)
    for key in obj:
        if key not in _POSTING_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    account = obj.get("account")
    if not isinstance(account, str):
        raise ExportError("%s: account is missing or not text" % where)
    note = obj.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    amount = obj.get("amount")
    if amount is not None:
        if not isinstance(amount, dict) or set(amount) != {"amount", "currency"} or not all(
            isinstance(v, str) for v in amount.values()
        ):
            raise ExportError("%s: amount must be null or an object with text keys amount and currency" % where)
        try:
            amount = Money.of(amount["amount"], amount["currency"])
        except (MoneyError, CurrencyError) as exc:
            raise ExportError("%s: invalid amount: %s" % (where, exc.message)) from None
    return Posting(account, amount, note)


def _tx_from_obj(obj, index):
    where = "transaction %d" % index
    if not isinstance(obj, dict):
        raise ExportError("%s: must be an object" % where)
    for key in obj:
        if key not in _TX_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    for key in ("date", "payee", "postings"):
        if key not in obj:
            raise ExportError("%s: missing key %r" % (where, key))
    date_text = obj["date"]
    if not isinstance(date_text, str):
        raise ExportError("%s: date must be text YYYY-MM-DD" % where)
    try:
        when = parse_date(date_text)
    except DateError as exc:
        raise ExportError("%s: %s" % (where, exc.message)) from None
    tid = obj.get("id")
    if tid is not None and (not _is_int(tid) or tid < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1" % where)
    flag = obj.get("flag", "*")
    if flag not in ("*", "!") or not isinstance(flag, str):
        raise ExportError("%s: flag must be '*' or '!'" % where)
    for key in ("payee", "narration"):
        if key in obj and not isinstance(obj[key], str):
            raise ExportError("%s: %s must be text" % (where, key))
    tags = obj.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    postings_obj = obj["postings"]
    if not isinstance(postings_obj, list):
        raise ExportError("%s: postings must be a list" % where)
    postings = [_posting_from_obj(p, "%s posting %d" % (where, i)) for i, p in enumerate(postings_obj, 1)]
    return Transaction(
        when, obj["payee"], obj.get("narration", ""), postings, tuple(sorted(set(tags))), flag, tid
    )


def transactions_from_json(text):
    if not isinstance(text, (str, bytes)):
        raise ExportError("JSON text expected, got %r" % (text,))
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as exc:
        raise ExportError("not valid JSON: %s" % exc) from None
    if not isinstance(data, list):
        raise ExportError("JSON must be an array of transactions")
    return [_tx_from_obj(obj, i) for i, obj in enumerate(data, 1)]

